-- V43: education agents use the same data-driven panel contract as commerce tools.
-- The schema lives on the agent row so each agent can be edited independently in the console.
UPDATE agents
SET ui_config_json = CASE child_classify
    WHEN '学习辅导' THEN '{"enabled":true,"title":"开始学习辅导","description":"先补充学习阶段和问题范围，智能体会按你的目标组织回答。","icon":"ri-book-open-line","submitLabel":"开始辅导","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学低年级","小学高年级","初中","高中","大学及以上"]},{"key":"subject","label":"学科","type":"select","required":true,"options":["语文","数学","英语","物理","化学","生物","历史","地理","其他"]},{"key":"goal","label":"学习目标","type":"text","required":true,"placeholder":"例如：弄懂一次函数的图像"},{"key":"content","label":"题目或材料","type":"textarea","required":true,"placeholder":"粘贴题目、答案或你的思路"}]}'
    WHEN '教师工具' THEN '{"enabled":true,"title":"配置教学任务","description":"确定课堂对象、课题和产出形式，生成后还可以继续修改。","icon":"ri-presentation-line","submitLabel":"生成教学方案","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学低年级","小学高年级","初中","高中","大学及以上"]},{"key":"subject","label":"学科","type":"select","required":true,"options":["语文","数学","英语","物理","化学","生物","历史","地理","综合"]},{"key":"topic","label":"课题或目标","type":"text","required":true,"placeholder":"例如：八年级物理·浮力"},{"key":"duration","label":"课时","type":"select","options":["20 分钟","40 分钟","45 分钟","90 分钟"]},{"key":"requirements","label":"补充要求","type":"textarea","placeholder":"班级人数、已有材料或评价要求"}]}'
    WHEN '家庭教育' THEN '{"enabled":true,"title":"描述家庭场景","description":"基于具体事实和沟通目标，获得更稳妥的建议。","icon":"ri-home-heart-line","submitLabel":"获取建议","fields":[{"key":"role","label":"你的身份","type":"select","required":true,"options":["家长","教师","其他照护者"]},{"key":"stage","label":"孩子学段","type":"select","required":true,"options":["幼儿园","小学","初中","高中","大学及以上"]},{"key":"scene","label":"发生场景","type":"text","required":true,"placeholder":"例如：放学后写作业容易拖延"},{"key":"goal","label":"希望达成的结果","type":"textarea","required":true,"placeholder":"你最希望这次沟通或调整解决什么"}]}'
    WHEN '语言学习' THEN '{"enabled":true,"title":"开始语言练习","description":"选择水平和场景，智能体会用短轮次陪你练习。","icon":"ri-translate-2","submitLabel":"开始练习","fields":[{"key":"language","label":"学习语言","type":"select","required":true,"options":["英语","日语","中文","其他"]},{"key":"level","label":"当前水平","type":"select","required":true,"options":["入门","基础","中级","高级"]},{"key":"scene","label":"练习场景","type":"text","required":true,"placeholder":"例如：酒店入住、面试、自我介绍"},{"key":"material","label":"已有文本或目标","type":"textarea","placeholder":"可粘贴作文、对话或想纠正的表达"}]}'
    WHEN '素质教育' THEN '{"enabled":true,"title":"设计探索任务","description":"告诉我年龄、兴趣和限制条件，生成适龄的探索方案。","icon":"ri-lightbulb-flash-line","submitLabel":"开始探索","fields":[{"key":"age","label":"年龄 / 学段","type":"select","required":true,"options":["幼儿园","小学","初中","高中","大学及以上"]},{"key":"topic","label":"主题","type":"text","required":true,"placeholder":"例如：植物观察、职业兴趣、情绪管理"},{"key":"materials","label":"现有材料或条件","type":"textarea","placeholder":"可选：时间、地点、材料、陪同者"},{"key":"safety","label":"需要安全提示","type":"checkbox","defaultValue":true}]}'
    WHEN '升学备考' THEN '{"enabled":true,"title":"制定备考计划","description":"先明确目标、时间和目前基础，再拆成可执行的阶段任务。","icon":"ri-calendar-check-line","submitLabel":"生成计划","fields":[{"key":"exam","label":"考试类型","type":"select","required":true,"options":["中考","高考","考研","公考","升学面试","其他"]},{"key":"stage","label":"当前阶段","type":"text","required":true,"placeholder":"例如：距离考试 100 天，刚完成一轮复习"},{"key":"subjects","label":"科目与基础","type":"textarea","required":true,"placeholder":"说明优势、短板和每天可投入时间"},{"key":"constraints","label":"限制条件","type":"textarea","placeholder":"作息、课程安排或目标偏好"}]}'
    ELSE '{"enabled":true,"title":"开始教育任务","description":"补充任务背景，智能体会根据你的目标组织回答。","icon":"ri-graduation-cap-line","submitLabel":"开始任务","fields":[{"key":"stage","label":"年级 / 学段","type":"select","required":true,"options":["小学","初中","高中","大学及以上"]},{"key":"goal","label":"任务目标","type":"text","required":true,"placeholder":"你希望完成什么"},{"key":"details","label":"补充说明","type":"textarea","required":true,"placeholder":"提供题目、材料或场景"}]}'
END
WHERE classify = 'AI 教育'
  AND status = 'ACTIVE';

-- The behaviour diagnosis agent needs one extra evidence slot, mirroring the reference site.
UPDATE agents
SET ui_config_json = '{"enabled":true,"title":"分析学生行为","description":"只记录可观察事实，帮助梳理可能原因和低风险支持方案。","icon":"ri-user-search-line","submitLabel":"开始分析","fields":[{"key":"role","label":"你的身份","type":"select","options":["教师","家长","辅导员","其他教育工作者"]},{"key":"stage","label":"学生学段","type":"select","required":true,"options":["幼儿园","小学","初中","高中","大学及以上"]},{"key":"scene","label":"发生场景","type":"select","options":["课堂活动","作业完成","小组合作","家庭沟通","同伴交往","其他"]},{"key":"behavior","label":"可观察行为","type":"textarea","required":true,"placeholder":"描述发生了什么、频率和持续时间，不要填写真实姓名或联系方式"},{"key":"evidence","label":"观察记录或图片说明","type":"upload","helpText":"图片或文件请在右侧对话框添加，并说明它与行为的关系"}]}'
WHERE agent_key = 'education-student-behavior-guide'
  AND classify = 'AI 教育';
